// Edit these non-secret settings. Store the owner token in an n8n Header Auth credential.
const settings = {
  baseUrl: 'http://127.0.0.1:3000',
  existingSlug: '', // Set to a saved project slug to resume; its saved config wins.
  operationId: 'podframes-n8n-' + $execution.id,
  pollSeconds: 70,
  maxStageMinutes: 120,
  config: {
    topic: 'Why is the sky blue?',
    language: 'en',
    targetDurationSec: 60,
    aspectRatio: '16:9',
    hosts: [
      { id: 'host_a', name: 'Ada', speaker: 'HOST_A', model: 'fish/drama-3',
        voice: 'ca3007f96ae7499ab87d27ea3599956a', side: 'left',
        persona: 'Warm, curious lead host',
        appearance: 'East Asian woman in her early 30s, straight black shoulder-length hair, olive blazer over a white tee' },
      { id: 'host_b', name: 'Theo', speaker: 'HOST_B', model: 'fish/drama-3',
        voice: '9a9cf47702da476aa4629e2506d4a857', side: 'right',
        persona: 'Lively co-host who grounds the discussion in specifics',
        appearance: 'Man in his late 30s, light stubble, glasses, charcoal henley' }
    ],
    options: { videoProvider: 'replicate-p-video', heygenAuth: 'subscription' }
  }
};
settings.baseUrl = settings.baseUrl.replace(/\/+$/, '');
if (!/^https?:\/\/[^\s?#]+$/.test(settings.baseUrl)) throw new Error('Set a reachable HTTP(S) baseUrl without query or fragment.');
if (!/^[A-Za-z0-9._-]{16,100}$/.test(settings.operationId)) throw new Error('operationId needs 16-100 letters, digits, dots, underscores or hyphens.');
if (settings.existingSlug && !/^[a-z0-9][a-z0-9-]*$/i.test(settings.existingSlug)) throw new Error('Invalid existing project slug.');
if (!Number.isInteger(settings.pollSeconds) || settings.pollSeconds < 1 || settings.pollSeconds > 3600) throw new Error('pollSeconds must be 1-3600.');
if (!Number.isInteger(settings.maxStageMinutes) || settings.maxStageMinutes < 1 || settings.maxStageMinutes > 180) throw new Error('maxStageMinutes must be 1-180.');
return [{ json: settings }];

const project = $input.first().json;
const settings = $('Episode settings').first().json;
if (!project.slug || !/^[a-z0-9][a-z0-9-]*$/i.test(project.slug)) throw new Error('API returned no valid project slug.');
if (project.runActive) throw new Error('This project already has an active run. Inspect Studio before starting another.');
return [{ json: { ...settings, slug: project.slug, options: project.options } }];

const health = $input.first().json;
const episode = $('Prepare episode').first().json;
const required = ['automation', 'worker', 'codex', 'fish', 'whisper', 'ffmpeg'];
if (episode.options.videoProvider === 'replicate-p-video') required.push('replicate');
if (episode.options.videoProvider === 'fal-ltx') required.push('fal');
if (episode.options.videoProvider === 'heygen' && episode.options.heygenAuth !== 'api') required.push('heygen');
const missing = required.filter(name => health[name] !== true);
if (missing.length) throw new Error('Backend not ready: ' + missing.join(', ') + '. Run doctor on the backend machine.');
return ['script', 'speech', 'stills', 'video', 'broll', 'compose', 'render'].map(stage => ({
  json: { baseUrl: episode.baseUrl, slug: episode.slug, operationId: episode.operationId,
    pollSeconds: episode.pollSeconds, maxStageMinutes: episode.maxStageMinutes, stage },
  pairedItem: { item: 0 }
}));

const context = $('Begin stage').item.json;
const project = $input.first().json;
if (project.slug !== context.slug || typeof project.runActive !== 'boolean') throw new Error('Unexpected project status response.');
const status = project.stages?.[context.stage];
const complete = project.runActive === false && status === 'done';
if (!project.runActive && !complete) {
  const reason = project.stageErrors?.[context.stage] || status || 'stage never started';
  throw new Error(context.stage + ' stopped: ' + reason + '. Inspect backend/provider state; no automatic retry.');
}
if (!complete && Date.now() >= context.deadline) throw new Error(context.stage + ' polling timed out. The backend job may still be running; inspect it before retrying.');
return [{ json: { ...context, complete, status, videoUrl: project.videoUrl ?? null } }];

const items = $input.all().map(item => item.json);
const result = items.find(item => item.stage === 'render');
if (!result?.complete || !result.videoUrl) throw new Error('Render finished without a video URL. Inspect project state.');
const prefix = '/api/media/' + result.slug + '/';
if (!result.videoUrl.startsWith(prefix)) throw new Error('Unexpected media URL; refusing to forward credentials.');
return [{ json: {
  slug: result.slug, stages: items.map(item => ({ stage: item.stage, status: item.status })),
  studioUrl: result.baseUrl + '/studio',
  downloadUrl: result.baseUrl + result.videoUrl.replace('/api/media/', '/api/v1/media/')
} }];
